var pathsWithMaxScore = function(board) {
    const m = board.length;
    const n = board[0].length;
    const MOD = 10 ** 9 + 7;

    board[0] = '0' + board[0].slice(1);

    const dp = Array.from({ length: m }, () => Array.from({ length: n }, () => Array(2).fill(0)));
